+   proto_tree_add_item_ret_uint(item_tree, hf_enip_hostname_len, tvb, offset, 1, ENC_LITTLE_ENDIAN, &name_length);
+
+   /* Host Name */
+   proto_tree_add_item(item_tree, hf_enip_hostname_hostname, tvb, offset + 1, name_length, ENC_ASCII);
+}
